export function submitOnboarding(data: MerchantOnboardingVO) {
  return request({
    url: "/mapi/WebApiJavaMerchPortal/api/mso/onboarding",
    method: "post",
    data,
  });
}

proxy: {
  // MSO 进件服务独立代理 - 不带 /sysp 前缀
  "/mapi/WebApiJavaMerchPortal": {
    changeOrigin: true,
    target: "http://192.168.100.190:37098",
    rewrite: (path) => {
      const newPath = path.replace(/^\/mapi\/WebApiJavaMerchPortal/, "");
      console.log(`[MSO代理] ${path} -> http://192.168.100.190:37098${newPath}`);
      return newPath;
    },
  },
  // MSO 接口带 /sysp 前缀时也走独立服务
  [`${env.VITE_APP_BASE_API}/mapi/WebApiJavaMerchPortal`]: {
    changeOrigin: true,
    target: "http://192.168.100.190:37098",
    rewrite: (path) => {
      const newPath = path.replace(
        new RegExp("^" + env.VITE_APP_BASE_API + "/mapi/WebApiJavaMerchPortal"),
        ""
      );
      console.log(`[MSO代理] ${path} -> http://192.168.100.190:37098${newPath}`);
      return newPath;
    },
  },
  /**
   * 反向代理解决跨域配置（通用）
   * http://localhost:3000/sys-api/users => http://localhost:8989/users
   */
  [env.VITE_APP_BASE_API]: {
    changeOrigin: true,
    target: env.VITE_APP_API_URL,
    rewrite: (path) =>
      path.replace(new RegExp("^" + env.VITE_APP_BASE_API + "/api"), ""),
  },
},
